// Pseudo-flow: boot -> attest -> CSR -> issue cert -> rotate
async function kcaFlow(device) {
  const attested = awaitTEEAttest(device);
  if(!attested) throw new Error('Attestation failed');
  const csr = awaitCreateCSR(device.spiffeId, 'edge-func');
  const cert = awaitKCA.issue(certRequestFromCSR(csr));
  awaitStoreCert(device, cert);
}
